1	'use client'
2	
3	import dynamic from 'next/dynamic'
4	import { useCallback, useState } from 'react'
5	import { useRouter, useSearchParams } from 'next/navigation'
6	import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
7	import { toast } from 'sonner'
8	import { Skeleton } from '@/components/ui/skeleton'
9	import { SmartBookingSheet } from '@/components/calendar/SmartBookingSheet'
10	import type { CalendarBooking } from '@/components/calendar/CalendarView'
11	import { useCalendarDrawer } from '@/hooks/calendar/use-calendar-drawer'
12	import { useBookingsRealtime } from '@/hooks/calendar/use-bookings-realtime'
13	import { PageShell } from '@/components/shared/PageShell'
14	
15	// Must be ssr:false — FullCalendar uses browser globals
16	const CalendarView = dynamic(
17	  () =>
18	    import('@/components/calendar/CalendarView').then((mod) => mod.CalendarView),
19	  {
20	    ssr: false,
21	    loading: () => (
22	      <div className="flex-1 p-4 space-y-3">
23	        <div className="flex items-center gap-3">
24	          <Skeleton className="h-9 w-32 rounded-lg" />
25	          <Skeleton className="h-9 w-24 rounded-lg" />
26	          <Skeleton className="h-9 w-24 rounded-lg" />
27	          <div className="ml-auto flex gap-2">
28	            <Skeleton className="h-9 w-9 rounded-lg" />
29	            <Skeleton className="h-9 w-20 rounded-lg" />
30	            <Skeleton className="h-9 w-9 rounded-lg" />
31	          </div>
32	        </div>
33	        <Skeleton className="h-[60vh] w-full rounded-xl" />
34	      </div>
35	    ),
36	  }
37	)
