39	// ── C7: URL search param helpers ────────────────────────────────────────────
40	function parseIds(value: string | null): string[] {
41	  if (!value) return []
42	  return value.split(',').filter(Boolean)
43	}
44	
45	function serializeIds(ids: string[]): string {
46	  return ids.join(',')
47	}
48	
49	interface CalendarPageClientProps {
50	  studioId: string
51	}
52	
53	export function CalendarPageClient({ studioId }: CalendarPageClientProps) {
54	  const router = useRouter()
55	  const searchParams = useSearchParams()
56	  const queryClient = useQueryClient()
57	
58	  // Realtime: keep calendar in sync when other users edit bookings
59	  useBookingsRealtime(studioId)
60	
61	  // ── C7: Lift filter state into URL ─────────────────────────────────────
62	  const filterArtistIds = parseIds(searchParams.get('artists'))
63	  const filterStatuses = parseIds(searchParams.get('statuses'))
64	  const filterServiceIds = parseIds(searchParams.get('services'))
65	
66	  function updateFilters(updates: {
67	    artists?: string[]
68	    statuses?: string[]
69	    services?: string[]
70	  }) {
71	    const next = new URLSearchParams(searchParams.toString())
72	    if (updates.artists !== undefined) {
73	      if (updates.artists.length > 0) {
74	        next.set('artists', serializeIds(updates.artists))
75	      } else {
76	        next.delete('artists')
77	      }
78	    }
79	    if (updates.statuses !== undefined) {
80	      if (updates.statuses.length > 0) {
81	        next.set('statuses', serializeIds(updates.statuses))
82	      } else {
83	        next.delete('statuses')
84	      }
85	    }
86	    if (updates.services !== undefined) {
87	      if (updates.services.length > 0) {
88	        next.set('services', serializeIds(updates.services))
89	      } else {
90	        next.delete('services')
91	      }
92	    }
93	    router.replace(`?${next.toString()}`, { scroll: false })
94	  }
95	
96	  // ── Date range state ──────────────────────────────────────────────────
97	  const [rangeStart, setRangeStart] = useState<string>(() => {
98	    const today = new Date()
99	    today.setHours(0, 0, 0, 0)
100	    return today.toISOString()
101	  })
102	  const [rangeEnd, setRangeEnd] = useState<string>(() => {
103	    const tomorrow = new Date()
104	    tomorrow.setDate(tomorrow.getDate() + 1)
105	    tomorrow.setHours(0, 0, 0, 0)
106	    return tomorrow.toISOString()
107	  })
108	
109	  // ── Drawer state ────────────────────────────────────────────────────────
110	  const {
111	    drawerOpen,
112	    setDrawerOpen,
113	    editingId,
114	    defaultStart,
115	    defaultEnd,
116	    defaultArtistId,
117	    openNew,
118	    openEdit,
119	  } = useCalendarDrawer()
120	
121	  const {
122	    data,
123	    isLoading,
124	    error,
125	    refetch,
126	  } = useQuery<{ data: CalendarBooking[]; count: number }>({
127	    queryKey: ['bookings', 'calendar', rangeStart, rangeEnd, filterArtistIds, filterStatuses],
128	    queryFn: async () => {
129	      const params = new URLSearchParams()
130	      params.set('from', rangeStart)
131	      params.set('to', rangeEnd)
132	      if (filterArtistIds.length > 0) params.set('artist_ids', filterArtistIds.join(','))
133	      if (filterStatuses.length > 0) params.set('statuses', filterStatuses.join(','))
134	
135	      const res = await fetch(`/api/bookings/calendar?${params.toString()}`)
136	      if (!res.ok) throw new Error('Failed to fetch bookings')
137	      return res.json() as Promise<{ data: CalendarBooking[]; count: number }>
138	    },
139	  })
140	
141	  type BookingsQuery = { data: CalendarBooking[]; count: number }
142	
143	  const rescheduleMutation = useMutation({
144	    mutationFn: async ({
145	      id,
146	      newStart,
147	      newEnd,
148	      newArtistId,
149	      suppressNotifications,
150	    }: {
151	      id: string
152	      newStart: Date
153	      newEnd: Date
154	      newArtistId?: string
155	      suppressNotifications?: boolean
156	    }) => {
157	      const durationMs = newEnd.getTime() - newStart.getTime()
158	      const duration_min = Math.round(durationMs / 60000)
159	      const body: Record<string, unknown> = {
160	        scheduled_at: newStart.toISOString(),
161	        duration_min,
162	      }
163	      if (newArtistId) body.artist_id = newArtistId
164	      if (suppressNotifications) body.suppress_notifications = true
165	      const res = await fetch(`/api/bookings/${id}`, {
166	        method: 'PATCH',
167	        headers: { 'Content-Type': 'application/json' },
168	        body: JSON.stringify(body),
169	      })
170	      if (!res.ok) {
171	        const err = await res.json() as { error?: string }
172	        throw new Error(err.error ?? 'Reschedule failed')
173	      }
174	      return res.json()
175	    },
176	    // ── Optimistic update: mutate cache immediately, roll back on error
177	    onMutate: async ({ id, newStart, newEnd, newArtistId }) => {
178	      await queryClient.cancelQueries({ queryKey: ['bookings', 'calendar'] })
179	
180	      const snapshots = queryClient.getQueriesData<BookingsQuery>({
181	        queryKey: ['bookings', 'calendar'],
182	      })
183	
184	      queryClient.setQueriesData<BookingsQuery>(
185	        { queryKey: ['bookings', 'calendar'] },
186	        (old) => {
187	          if (!old) return old
188	          return {
189	            ...old,
190	            data: old.data.map((b) => {
191	              if (b.id !== id) return b
192	              const durationMin = Math.round(
193	                (newEnd.getTime() - newStart.getTime()) / 60000
194	              )
195	              return {
196	                ...b,
197	                scheduled_at: newStart.toISOString(),
198	                end_at: newEnd.toISOString(),
199	                duration_min: durationMin,
200	                ...(newArtistId && b.artist.id !== newArtistId
201	                  ? { artist: { ...b.artist, id: newArtistId } }
202	                  : {}),
203	              }
204	            }),
205	          }
206	        }
207	      )
208	
209	      return { snapshots }
210	    },
211	    onError: (_err, _vars, context) => {
212	      if (!context?.snapshots) return
213	      // Rollback to pre-mutation snapshot
214	      context.snapshots.forEach(([key, data]) => {
215	        queryClient.setQueryData(key, data)
216	      })
217	    },
218	    onSettled: () => {
219	      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
220	    },
221	  })
222	
223	  const handleReschedule = useCallback(
224	    async (
225	      id: string,
226	      newStart: Date,
227	      newEnd: Date,
228	      newArtistId?: string,
229	      opts?: { suppressNotifications?: boolean }
230	    ) => {
231	      const payload: {
232	        id: string
233	        newStart: Date
234	        newEnd: Date
235	        newArtistId?: string
236	        suppressNotifications?: boolean
237	      } = { id, newStart, newEnd }
238	      if (newArtistId) payload.newArtistId = newArtistId
239	      if (opts?.suppressNotifications) payload.suppressNotifications = true
240	      await rescheduleMutation.mutateAsync(payload)
241	    },
242	    [rescheduleMutation]
243	  )
244	
245	  const bookings = data?.data ?? []
246	  const totalBookings = data?.count ?? 0
247	
248	  return (
249	    <PageShell fullHeight>
250	      <CalendarView
251	        bookings={bookings}
252	        isLoading={isLoading}
253	        error={error ? (error instanceof Error ? error.message : 'Unknown error') : null}
254	        totalBookings={totalBookings}
255	        rangeStart={rangeStart}
256	        rangeEnd={rangeEnd}
257	        onViewDatesChange={(start: Date, end: Date) => {
258	          setRangeStart(start.toISOString())
259	          setRangeEnd(end.toISOString())
260	        }}
261	        filterArtistIds={filterArtistIds}
262	        filterStatuses={filterStatuses}
263	        filterServiceIds={filterServiceIds}
264	        onArtistFilterChange={(ids) => updateFilters({ artists: ids })}
265	        onStatusFilterChange={(statuses) => updateFilters({ statuses })}
266	        onServiceFilterChange={(ids) => updateFilters({ services: ids })}
267	        onNewAppointment={openNew}
268	        onEditAppointment={openEdit}
269	        onReschedule={handleReschedule}
270	        onRetry={() => {
271	          void refetch()
272	        }}
273	      />
274	
275	      <SmartBookingSheet
276	        open={drawerOpen}
277	        onOpenChange={setDrawerOpen}
278	        defaultStart={defaultStart}
279	        defaultEnd={defaultEnd}
280	        defaultArtistId={defaultArtistId}
281	        editingId={editingId}
282	        onSuccess={() => {
283	          setDrawerOpen(false)
284	          toast.success('Booking created')
285	        }}
286	      />
287	    </PageShell>
288	  )
289	}
